import{_ as a,o as s,c as t,a0 as i}from"./chunks/framework.B1UNJuMu.js";const g=JSON.parse('{"title":"Languages","description":"","frontmatter":{},"headers":[],"relativePath":"task/languages.md","filePath":"task/languages.md"}'),n={name:"task/languages.md"};function o(l,e,d,h,r,c){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="languages" tabindex="-1">Languages <a class="header-anchor" href="#languages" aria-label="Permalink to &quot;Languages&quot;">​</a></h1><p>A contest can have its statements in several languages. Students choose the language from the navigation bar and can switch at any time during the contest, without losing their answers. Every language is graded the same way: there is a single set of correct answers for each variant.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>List the languages in <strong>both</strong> <code>data/contests.toml</code> and <code>data/variants.toml</code>, with the same values. The first language is the default one:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">my-contest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">languages = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;it&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;en&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>Languages are two-letter lowercase codes (<code>it</code>, <code>en</code>, <code>de</code>, ...). Contests without <code>languages</code> have a single language, <code>it</code>, and work exactly as before.</p><h2 id="translating-problems" tabindex="-1">Translating problems <a class="header-anchor" href="#translating-problems" aria-label="Permalink to &quot;Translating problems&quot;">​</a></h2><p>The statement in the default language is always <code>question.md</code> (or <code>question.mdx</code>). Each translation is a file named <code>question.&lt;lang&gt;.md</code> in the same folder:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>p-1-salto-ostacoli/</span></span>
<span class="line"><span>├── question.md        # default language (the first in \`languages\`)</span></span>
<span class="line"><span>├── question.en.md     # English</span></span>
<span class="line"><span>├── fig.asy            # shared by all languages</span></span>
<span class="line"><span>└── variants.py        # shared by all languages</span></span></code></pre></div><p>A translation must have <strong>the same answers</strong> as the default statement:</p><ul><li>the same sub-questions (the same <code>---</code> separators);</li><li>the same answer types;</li><li>the same options, in the same order, with the same correct ones;</li><li>the same values for open answers.</li></ul><p><code>quizms variants</code> checks this and fails if a translation is graded differently, for example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✗ The en statement of variant demo/10 doesn&#39;t match the it statement at [&quot;1.2&quot;][&quot;options&quot;][0][&quot;correct&quot;].</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The check compares answers, not text. If a translation swaps two wrong options, the check passes, but the same stored answer refers to different text in the two languages. Keep the options in the same order.</p></div><h3 id="variants-and-images" tabindex="-1">Variants and images <a class="header-anchor" href="#variants-and-images" aria-label="Permalink to &quot;Variants and images&quot;">​</a></h3><p>Every language of a problem uses the same variant for a given student. Variants are defined in each file, so all translations must define <strong>the same variants</strong>, in the same order. The easiest way is to keep them in a shared file, imported by every translation:</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">import variants from &quot;./variants.py&quot;;</span></span></code></pre></div><p>Images are imported by each file, so translations can share them (<code>![fig](fig.asy)</code>) or use a translated copy (<code>![fig](fig.en.asy)</code>).</p><h3 id="missing-translations" tabindex="-1">Missing translations <a class="header-anchor" href="#missing-translations" aria-label="Permalink to &quot;Missing translations&quot;">​</a></h3><p>Every problem used by the contest must have a statement in every language: <code>quizms variants</code>, <code>quizms print</code> and <code>quizms firebase import</code> fail and list the missing files. Problem folders that are not used in <code>contest.mdx</code> are not checked.</p><p>The only exception is <code>quizms dev</code>: a missing translation shows the default language with a warning, so you can preview a contest while it is still being translated.</p><h2 id="translating-the-contest-page" tabindex="-1">Translating the contest page <a class="header-anchor" href="#translating-the-contest-page" aria-label="Permalink to &quot;Translating the contest page&quot;">​</a></h2><p>Text in <code>contest.mdx</code> (section titles, explanations) can be translated with <code>&lt;Locale&gt;</code>:</p><div class="language-mdx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mdx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;Locale lang=&quot;it&quot;&gt;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Sezione 1: quiz</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/Locale&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;Locale lang=&quot;en&quot;&gt;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Section 1: quizzes</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/Locale&gt;</span></span></code></pre></div><p><code>&lt;Locale&gt;</code> is only for text: <code>&lt;Problem&gt;</code> and <code>&lt;Section&gt;</code> cannot be inside it.</p><p>The contest header (<code>header</code> in <code>variants.toml</code>, e.g. <code>header.md</code>) is translated with <code>header.&lt;lang&gt;.md</code> files in the same folder.</p><h2 id="building" tabindex="-1">Building <a class="header-anchor" href="#building" aria-label="Permalink to &quot;Building&quot;">​</a></h2><p><code>quizms variants</code> builds every language. For each variant it writes <code>statement.&lt;lang&gt;.txt</code>, plus <code>statement.txt</code> for the default language. <code>quizms print</code> writes <code>statement.&lt;lang&gt;.pdf</code>, plus <code>statement.pdf</code> for the default language.</p><p>Both commands accept <code>--languages</code> to build only some languages, overriding the configuration. The first one is the default language of that run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">quizms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> variants</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --languages=en</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">quizms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> print</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --languages=it,en</span></span></code></pre></div><p><code>quizms print</code> uses the statements built by <code>quizms variants</code>, so run both with the same languages.</p><h2 id="what-is-translated" tabindex="-1">What is translated <a class="header-anchor" href="#what-is-translated" aria-label="Permalink to &quot;What is translated&quot;">​</a></h2><p>QuizMS translates the fixed text that is part of the statements: question headings (<code>Domanda 1</code> / <code>Question 1</code>), the PDF footer (<code>Variante</code> / <code>Variant</code>), the fields printed on the PDF (<code>Codice prova</code> / <code>Test code</code>), the blank-page note of the teacher&#39;s PDF, and in <a href="./blockly.html">block programming</a> problems the built-in blocks and the default toolbox categories. Italian and English are available; other languages use English.</p><p>Text written by the problem author is not translated automatically: custom blocks, custom toolboxes and visualizers can be translated by importing different files in each translation.</p><p>The rest of the interface (menus, buttons, messages) stays in Italian, and so do the values in the configuration files: contest names and the labels of the personal data fields (<code>user_data</code>).</p><h2 id="firebase" tabindex="-1">Firebase <a class="header-anchor" href="#firebase" aria-label="Permalink to &quot;Firebase&quot;">​</a></h2><ul><li>The student&#39;s choice is saved, so it is kept after reloading the page or changing device. The choice is saved through the QuizMS Cloud Functions, so deploy them after updating QuizMS: with older functions, the choice is not saved.</li><li><code>quizms firebase import</code> checks that every language of each contest has its statements (and its PDFs, if they were generated) before uploading them.</li><li>Teachers choose the language of the PDFs they download from the dashboard.</li></ul>`,37)])])}const u=a(n,[["render",o]]);export{g as __pageData,u as default};
